#!/usr/bin/env python3
# Writes std/case_tables.cy, std's Unicode case tables, from Unicode's own files (owner, 2026-10-21: "(a)",
# generated CyborgPL source; Python, the files downloaded from unicode.org).
#
#   python3 -I std/tools/case_tables.py <folder holding the four files> std/case_tables.cy
#
# The four files, from https://www.unicode.org/Public/17.0.0/ucd/ (the version kayo pins; `kayo version`):
# UnicodeData.txt, SpecialCasing.txt, DerivedCoreProperties.txt and PropList.txt. Only the generated file goes
# in the repository, with Unicode's licence notice (std/tools/UNICODE-LICENSE).
#
# Each table is sorted const arrays and a function that searches them by halves, written out step by step,
# so every read of an array sits right behind the check that it is inside.

import os
import sys

UNICODE = "17.0.0"


def read_lines(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.split("#", 1)[0].strip()
            if line:
                yield line


def unicode_data(folder):
    """Simple mappings and combining classes from UnicodeData.txt, ranges like <CJK …, First> included."""
    upper, lower, ccc = {}, {}, {}
    first = None
    for line in read_lines(os.path.join(folder, "UnicodeData.txt")):
        f = line.split(";")
        cp = int(f[0], 16)
        if f[1].endswith(", First>"):
            first = cp
            continue
        start = first if f[1].endswith(", Last>") else cp
        first = None
        for c in range(start, cp + 1):
            if f[3] != "0":
                ccc[c] = int(f[3])
            if f[12]:
                upper[c] = int(f[12], 16)
            if f[13]:
                lower[c] = int(f[13], 16)
    return upper, lower, ccc


def special_casing(folder):
    """The unconditional full mappings of SpecialCasing.txt (lines with a condition are std's own code)."""
    upper, lower = {}, {}
    for line in read_lines(os.path.join(folder, "SpecialCasing.txt")):
        f = [x.strip() for x in line.split(";")]
        if len(f) > 4 and f[4]:
            continue
        cp = int(f[0], 16)
        lo = [int(x, 16) for x in f[1].split()]
        up = [int(x, 16) for x in f[3].split()]
        if lo != [cp]:
            lower[cp] = lo
        if up != [cp]:
            upper[cp] = up
    return upper, lower


def property_ranges(path, name):
    ranges = []
    for line in read_lines(path):
        f = [x.strip() for x in line.split(";")]
        if f[1] != name:
            continue
        if ".." in f[0]:
            a, b = f[0].split("..")
            ranges.append((int(a, 16), int(b, 16)))
        else:
            c = int(f[0], 16)
            ranges.append((c, c))
    ranges.sort()
    merged = []
    for a, b in ranges:
        if merged and a <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], b))
        else:
            merged.append((a, b))
    return merged


def runs(codes):
    """Code points as merged ranges."""
    out = []
    for c in sorted(codes):
        if out and c == out[-1][1] + 1:
            out[-1] = (out[-1][0], c)
        else:
            out.append((c, c))
    return out


def const(name, values):
    body, line = [], "   "
    for v in values:
        piece = f" {v},"
        if len(line) + len(piece) > 110:
            body.append(line)
            line = "   "
        line += piece
    body.append(line)
    return f"pub.kit const ${name}: arr[u32] := [\n" + "\n".join(body) + "\n];\n"


def search(fn, keys, n, doc):
    """A function giving the last position whose key is at most 'c', or 0: halves, unrolled."""
    lines = [f"# {doc}", f"pub.kit fn {fn} [$c: u32] -> u64:",
             f"    let $n := arr.len(${keys});",
             f"    var $p: u64[max: {n}] = 0;"]
    b = 1
    while b * 2 <= n:
        b *= 2
    while b >= 1:
        lines.append(f"    if $p + {b} <= $n and.then ${keys}[pos: $p + {b}] <= $c:")
        lines.append(f"        change $p to $p + {b};")
        lines.append("    ;if")
        b //= 2
    lines.append("    ret $p;")
    lines.append(f";fn {fn}\n")
    return "\n".join(lines)


def main():
    folder, out_path = sys.argv[1], sys.argv[2]
    simple_up, simple_low, ccc = unicode_data(folder)
    full_up, full_low = special_casing(folder)
    derived = os.path.join(folder, "DerivedCoreProperties.txt")
    cased = property_ranges(derived, "Cased")
    ignorable = property_ranges(derived, "Case_Ignorable")
    soft = property_ranges(os.path.join(folder, "PropList.txt"), "Soft_Dotted")
    above = runs(c for c, k in ccc.items() if k == 230)
    marks = runs(ccc.keys())

    parts = [f"""# GENERATED by std/tools/case_tables.py from Unicode {UNICODE}'s UnicodeData.txt, SpecialCasing.txt,
# DerivedCoreProperties.txt and PropList.txt (https://www.unicode.org/Public/{UNICODE}/ucd/). Do not edit by hand:
# change the generator and run it again. Unicode's data is under the Unicode License v3 (std/tools/UNICODE-LICENSE).
#
# std's case tables (owner, 2026-10-21: "(a)", a generated module of consts). Each pair table maps a code point,
# its keys sorted; each range table lists runs of code points, lo and hi. A search gives the last position whose
# key is at most 'c', or 0 when there is none.
"""]

    def pair(name, table, doc):
        keys = sorted(table)
        parts.append(const(f"{name}_keys", keys))
        parts.append(const(f"{name}_values", [table[k] for k in keys]))
        parts.append(search(f"{name}_at", f"{name}_keys", len(keys), doc))
        parts.append(f"""# 'c' mapped by {name}, or 'c' itself when it has no mapping.
pub.kit fn {name} [$c: u32] -> u32:
    let $p := {name}_at($c);
    if $p >= 1 and.then $p <= arr.len(${name}_keys) and.then ${name}_keys[pos: $p] == $c
        and.then $p <= arr.len(${name}_values):
        ret ${name}_values[pos: $p];
    ;if
    ret $c;
;fn {name}
""")

    def seq(name, table, doc):
        keys = sorted(table)
        parts.append(const(f"{name}_keys", keys))
        for i in range(3):
            parts.append(const(f"{name}_{i + 1}", [table[k][i] if i < len(table[k]) else 0 for k in keys]))
        parts.append(search(f"{name}_at", f"{name}_keys", len(keys), doc))
        parts.append(f"""# Whether 'c' has a longer mapping in {name}.
pub.kit fn {name}_has [$c: u32] -> bool:
    let $p := {name}_at($c);
    ret $p >= 1 and.then $p <= arr.len(${name}_keys) and.then ${name}_keys[pos: $p] == $c;
;fn {name}_has
""")
        for i in range(3):
            parts.append(f"""# The code point number {i + 1} of 'c''s longer mapping in {name}, or 0 when there is none.
pub.kit fn {name}_{i + 1}_of [$c: u32] -> u32:
    let $p := {name}_at($c);
    if $p >= 1 and.then $p <= arr.len(${name}_keys) and.then ${name}_keys[pos: $p] == $c
        and.then $p <= arr.len(${name}_{i + 1}):
        ret ${name}_{i + 1}[pos: $p];
    ;if
    ret 0;
;fn {name}_{i + 1}_of
""")

    def ranges(name, rs, doc):
        parts.append(const(f"{name}_lo", [a for a, b in rs]))
        parts.append(const(f"{name}_hi", [b for a, b in rs]))
        parts.append(search(f"{name}_at", f"{name}_lo", len(rs), doc))
        parts.append(f"""# Whether 'c' is in {name}.
pub.kit fn {name} [$c: u32] -> bool:
    let $p := {name}_at($c);
    ret $p >= 1 and.then $p <= arr.len(${name}_hi) and.then ${name}_hi[pos: $p] >= $c;
;fn {name}
""")

    pair("simple_upper", simple_up, "Unicode's simple uppercase: one code point for one.")
    pair("simple_lower", simple_low, "Unicode's simple lowercase: one code point for one.")
    seq("full_upper", {k: v for k, v in full_up.items() if len(v) <= 3}, "SpecialCasing's unconditional uppercase, up to three code points (0: none).")
    seq("full_lower", {k: v for k, v in full_low.items() if len(v) <= 3}, "SpecialCasing's unconditional lowercase, up to three code points (0: none).")
    ranges("cased", cased, "Cased (DerivedCoreProperties), for final sigma.")
    ranges("case_ignorable", ignorable, "Case_Ignorable (DerivedCoreProperties), for final sigma.")
    ranges("soft_dotted", soft, "Soft_Dotted (PropList), for the Lithuanian rules.")
    ranges("above", above, "Combining class 230, Above, for the Lithuanian and Turkish rules.")
    ranges("marks", marks, "Any combining class but 0, for the Lithuanian and Turkish rules.")

    with open(out_path, "w", encoding="utf-8") as f:
        f.write("\n".join(parts))


if __name__ == "__main__":
    main()
